"""Build one self-contained, offline scoreboard from verified judge results."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
RESULT_ROOT = ROOT

TEMPLATE = r'''<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Packing Arena: AI Agent Algorithm Tournament</title>
<meta name="description" content="A reproducible AI-assisted bin-packing tournament with three algorithms, peer reviews, 108 synthetic cases, and an interactive results explorer.">
<style>
:root{color-scheme:dark;--bg:#101414;--panel:#191e1e;--line:#343e3b;--ink:#f0f0df;--muted:#a9b3aa;--accent:#d7fc70;--scarlet:#ff897e;--cobalt:#8aafff;--jade:#70ddab}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 system-ui,sans-serif}main{max-width:1220px;margin:auto;padding:40px 28px 80px}a{color:var(--accent)}.eyebrow{font:12px/1.5 ui-monospace,monospace;letter-spacing:.13em;color:var(--accent);text-transform:uppercase}header{padding:30px 0 36px;border-bottom:1px solid var(--line)}h1{font-size:clamp(44px,8vw,90px);line-height:.98;letter-spacing:-.065em;margin:18px 0 22px}h1 span{color:var(--accent)}h2{font-size:24px;letter-spacing:-.04em;margin:0 0 8px}h3{margin:0;font-size:18px}.intro{max-width:690px;color:var(--muted);font-size:17px}.meta{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}.pill{border:1px solid var(--line);padding:6px 12px;font:12px/1.5 ui-monospace,monospace}.toolbar{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin:30px 0 20px}select,button{background:var(--panel);color:var(--ink);border:1px solid #57655f;padding:10px 14px;border-radius:4px;font:inherit}button{cursor:pointer}button.active{background:var(--accent);color:#182018;border-color:var(--accent)}button:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid white;outline-offset:3px}.spacer{flex:1}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:var(--panel);border:1px solid var(--line);padding:24px;position:relative}.card.winner{border-color:var(--accent)}.rank{font:12px/1.5 ui-monospace,monospace;color:var(--muted)}.name{font-size:30px;letter-spacing:-.04em;font-weight:700}.big{font-size:52px;line-height:1.15;letter-spacing:-.05em;margin:16px 0 0;font-variant-numeric:tabular-nums}.muted{color:var(--muted)}.small{font-size:12px}.bar{height:5px;background:#303a32;margin:18px 0}.bar span{height:100%;display:block}.metrics{display:flex;gap:16px;flex-wrap:wrap;font-size:13px}.verdict{border-left:3px solid var(--accent);padding:14px 22px;background:#1b241b;margin:22px 0 40px}.section{margin:42px 0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-variant-numeric:tabular-nums}th,td{padding:12px 14px;border-bottom:1px solid var(--line)}th{font-size:12px;color:var(--muted);font-weight:500}td:not(:first-child),th:not(:first-child){text-align:right}.best{color:var(--accent)}.packing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.packing-panel{background:var(--panel);border:1px solid var(--line);padding:18px;max-height:640px;overflow:auto}.box{height:25px;display:flex;background:#0c1010;border:1px solid #4c5953;margin:6px 0;position:relative}.item{display:flex;align-items:center;justify-content:center;font:10px ui-monospace,monospace;color:#101414;overflow:hidden;border-right:1px solid #101414}.box small{position:absolute;right:3px;top:1px;font:9px ui-monospace,monospace;color:#fff;background:#101414c9;padding:0 2px}.case-note{margin:10px 0 18px;color:var(--muted)}.review-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}details{border:1px solid var(--line);padding:16px;background:var(--panel)}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.7 ui-monospace,monospace;color:var(--muted)}footer{margin-top:45px;padding-top:25px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}.foot-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.hash{word-break:break-all;font-family:ui-monospace,monospace}#phase-status{color:var(--muted);font-size:13px}@media(max-width:760px){main{padding:22px 16px 50px}.cards,.packing-grid,.review-grid,.foot-grid{grid-template-columns:1fr}.packing-panel{max-height:370px}h1{font-size:60px}.big{font-size:44px}.card{padding:18px}.toolbar{gap:10px}}
</style></head><body><main>
<header><div class="eyebrow">Experiment 001 / 24-25 Oktober 2026</div><h1>PACKING<br><span>ARENA.</span></h1>
<p class="intro">Tiga agen. Aturan sama. Satu tujuan: susun semua barang ke kardus sesedikit mungkin. Kritik silang dulu, pengujian tersembunyi setelah kode final.</p>
<p class="muted small">Proyek eksperimen dengan bantuan AI. Ketiga agen memakai model induk yang sama. Seluruh kasus memakai data sintetis.</p>
<div class="meta"><span class="pill">3 AGEN INDEPENDEN</span><span class="pill">108 KASUS TERKUNCI</span><span class="pill">KAPASITAS 100</span><span class="pill">3 PENGULANGAN</span></div></header>
<div class="toolbar"><button id="final" class="active" aria-pressed="true">Setelah kritik</button><button id="initial" aria-pressed="false">Sebelum kritik</button><span class="spacer"></span><span id="phase-status"></span></div>
<div class="cards" id="scores" aria-live="polite"></div><div class="verdict" id="verdict"></div>
<section class="section"><h2>Apakah kritik membantu?</h2><p class="muted">Kedua versi diuji pada dataset yang sama. Angka negatif berarti kardus berkurang.</p><div class="table-wrap"><table><thead><tr><th scope="col">AGEN</th><th scope="col">AWAL</th><th scope="col">FINAL</th><th scope="col">PERUBAHAN</th><th scope="col">MEDIAN FINAL</th></tr></thead><tbody id="changes"></tbody></table></div></section>
<section class="section"><h2>Hasil per jenis kasus</h2><p class="muted">Jumlah kardus keluaran per kelompok. Angka tetap ditampilkan bila waktu gagal. Baseline memakai best-fit decreasing.</p><div class="table-wrap"><table><thead><tr><th scope="col">KELOMPOK</th><th scope="col">KASUS</th><th scope="col">SCARLET</th><th scope="col">COBALT</th><th scope="col">JADE</th><th scope="col">BASELINE</th></tr></thead><tbody id="families"></tbody></table></div></section>
<section class="section"><h2>Lihat isi kardusnya</h2><p class="muted">Lebar balok menunjukkan bobot barang. Area gelap menunjukkan kapasitas kosong. Arahkan kursor ke balok untuk melihat indeks barang.</p>
<div class="toolbar"><label for="family">Kelompok</label><select id="family"><option value="all">Semua kelompok</option></select><label for="case">Kasus</label><select id="case"></select><button id="next">Kasus berikutnya</button></div><p class="case-note" id="case-note"></p><div class="packing-grid" id="packing"></div></section>
<section class="section"><h2>Kritik silang</h2><p class="muted">Setiap agen membaca satu snapshot lawan. Mereka tidak menerima skor atau kasus tersembunyi sebelum revisi.</p><div class="review-grid">__REVIEWS__</div></section>
<section class="section"><h2>Kode dan bukti</h2><p class="muted">Seluruh hasil tersedia offline. Snapshot awal tersimpan di folder round1.</p><div class="review-grid">__SOURCES__</div></section>
<footer><div class="foot-grid"><div>Ranking: validitas, total kardus, lalu median waktu. Total kardus membobot setiap kasus satu kali. Kasus besar memberi kontribusi lebih besar. Waktu hanya mencakup solve, tanpa impor atau validasi. Urutan peserta dirotasi. Waktu lokal dapat berubah saat pengujian ulang.<br><br>Ini perbandingan tiga solusi agen dengan model induk yang sama. Satu turnamen tidak membuktikan algoritma terbaik untuk semua input.</div><div><span id="exact-note"></span><br><br>Seed: <span id="seed"></span><br>SHA-256 dataset:<br><span class="hash" id="hash"></span><br><br><a href="results.json">Data hasil</a> · <a href="cases.json">Dataset</a> · <a href="judge.py">Kode juri</a> · <a href="RULES.txt">Aturan</a> · <a href="README.txt">Cara menjalankan</a> · <a href="https://github.com/vanovri/packing-arena">GitHub</a></div></div></footer>
</main><script>
const DATA = __DATA__;
const names=['scarlet','cobalt','jade'];let phase='final';
const $=id=>document.getElementById(id);const title=s=>s[0].toUpperCase()+s.slice(1);const fmt=n=>n.toLocaleString('id-ID');const ms=n=>n.toFixed(3)+' ms';
function byName(p,n){return DATA.rounds[p].find(x=>x.name===n)}
function selectCases(){const family=$('family').value;const old=$('case').value;$('case').replaceChildren();DATA.cases.filter(c=>family==='all'||c.family===family).forEach(c=>{const o=document.createElement('option');o.value=c.id;o.textContent=c.id+' · '+c.items.length+' barang';$('case').append(o)});if([...$('case').options].some(o=>o.value===old))$('case').value=old;renderPacking()}
function renderPacking(){const c=DATA.cases.find(c=>c.id===$('case').value);if(!c)return;const total=c.items.reduce((a,b)=>a+b,0);$('case-note').textContent=c.id+' / '+c.family+' / '+c.items.length+' barang / bobot total '+total+' / '+(c.optimum!==null?'optimum terbukti '+c.optimum:'batas bawah '+c.lower_bound+', optimum belum dibuktikan');$('packing').replaceChildren();names.forEach(n=>{const row=byName(phase,n).rows.find(r=>r.id===c.id);const panel=document.createElement('div');panel.className='packing-panel';const h=document.createElement('h3');h.style.color='var(--'+n+')';h.textContent=title(n)+' · '+row.bins+' kardus';panel.append(h);if(row.error){const p=document.createElement('p');p.textContent=row.error==='Exceeded 1 second'?'Melewati batas waktu 1 detik.':row.error;panel.append(p)}row.packing.forEach(box=>{const bin=document.createElement('div');bin.className='box';box.forEach(i=>{const item=document.createElement('span');item.className='item';item.style.width=c.items[i]+'%';item.style.background='hsl('+((i*47)%360)+' 52% 70%)';item.title='Barang #'+i+': bobot '+c.items[i];item.textContent=c.items[i]>=7?c.items[i]:'';bin.append(item)});const load=document.createElement('small');load.textContent=box.reduce((a,i)=>a+c.items[i],0)+'/100';bin.append(load);panel.append(bin)});if(!row.packing.length){const p=document.createElement('p');p.className='muted';p.textContent='Tidak ada barang.';panel.append(p)}$('packing').append(panel)})}
function render(){const scores=DATA.rounds[phase];const baseline=DATA.baseline.reduce((a,b)=>a+b,0);const best=scores[0];$('scores').innerHTML=scores.map((s,i)=>'<article class="card '+(!i?'winner':'')+'"><div class="rank">PERINGKAT 0'+(i+1)+'</div><div class="name" style="color:var(--'+s.name+')">'+title(s.name)+'</div><div class="big">'+(s.invalid?'GAGAL':fmt(s.total_bins))+'</div><div class="muted">'+(s.invalid?'kasus melewati aturan':'total kardus')+'</div><div class="bar"><span style="width:'+Math.min(100,best.total_bins/Math.max(s.total_bins,1)*100)+'%;background:var(--'+s.name+')"></span></div><div class="metrics"><span>'+s.invalid+' kasus gagal</span><span>Median '+ms(s.median_ms)+'</span></div><div class="small muted">Terburuk '+ms(s.max_ms)+(s.invalid?' · '+fmt(s.rows.reduce((a,r)=>a+r.bins,0))+' kardus keluaran':'')+'</div></article>').join('');const equal=scores.filter(s=>s.invalid===best.invalid&&s.total_bins===best.total_bins).length;$('verdict').textContent=title(best.name)+' memimpin '+(equal>1?'melalui pemecah seri waktu. ':'dengan total kardus terendah. ')+(baseline-best.total_bins)+' kardus lebih sedikit dari baseline ('+fmt(baseline)+'). '+(phase==='final'?'Hasil setelah kritik silang.':'Snapshot sebelum kritik silang.');$('phase-status').textContent=(phase==='final'?'VERSI FINAL':'SNAPSHOT AWAL')+' / 108 KASUS';for(const p of ['final','initial']){$(p).classList.toggle('active',phase===p);$(p).setAttribute('aria-pressed',String(phase===p))}
$('changes').innerHTML=names.map(n=>{const a=byName('initial',n),b=byName('final',n),delta=b.total_bins-a.total_bins;return '<tr><td>'+title(n)+'</td><td>'+fmt(a.total_bins)+'</td><td>'+(b.invalid?'Gagal '+b.invalid+' kasus':fmt(b.total_bins))+'</td><td class="'+(!b.invalid&&delta<0?'best':'')+'">'+(b.invalid?'Tidak dibandingkan':(delta>0?'+':'')+delta)+'</td><td>'+ms(b.median_ms)+'</td></tr>'}).join('');const families=[...new Set(DATA.cases.map(c=>c.family))];$('families').innerHTML=families.map(f=>{const indices=DATA.cases.map((c,i)=>c.family===f?i:-1).filter(i=>i>=0);const totals=names.map(n=>indices.reduce((s,i)=>s+byName(phase,n).rows[i].bins,0));const base=indices.reduce((s,i)=>s+DATA.baseline[i],0);return '<tr><td>'+f+'</td><td>'+indices.length+'</td>'+totals.map(v=>'<td class="'+(v===Math.min(...totals)?'best':'')+'">'+fmt(v)+'</td>').join('')+'<td>'+fmt(base)+'</td></tr>'}).join('');renderPacking()}
for(const f of [...new Set(DATA.cases.map(c=>c.family))]){const o=document.createElement('option');o.value=f;o.textContent=f;$('family').append(o)}
for(const p of ['final','initial'])$(p).addEventListener('click',()=>{phase=p;render()});$('family').addEventListener('change',selectCases);$('case').addEventListener('change',renderPacking);$('next').addEventListener('click',()=>{$('case').selectedIndex=($('case').selectedIndex+1)%$('case').options.length;renderPacking()});$('seed').textContent=DATA.seed;$('hash').textContent=DATA.dataset_sha256;const exact=DATA.cases.filter(c=>c.optimum!==null);$('exact-note').textContent=exact.length+' kasus memiliki optimum persis melalui pencarian menyeluruh dengan pruning. Kasus lain memakai batas bawah. Output diperiksa: kapasitas, indeks, input tetap utuh, dan determinisme.';selectCases();const interesting=DATA.cases.find((c,i)=>names.some(n=>byName('final',n).rows[i].error))||DATA.cases.find((c,i)=>new Set(names.map(n=>byName('final',n).rows[i].bins)).size>1)||DATA.cases.find(c=>c.items.length>=20);if(interesting)$('case').value=interesting.id;render();
</script></body></html>'''


def main():
    data = json.loads((RESULT_ROOT / 'results.json').read_text(encoding='utf-8'))
    reviews = []
    sources = []
    for name in ['scarlet', 'cobalt', 'jade']:
        review = (RESULT_ROOT / f'review-{name}.txt').read_text(encoding='utf-8')
        reviews.append(f'<details><summary>Kritik dari {name.title()}</summary><pre>{html.escape(review)}</pre></details>')
        code = (RESULT_ROOT / f'{name}.py').read_text(encoding='utf-8')
        sources.append(f'<details><summary>{name.title()} / kode final</summary><pre>{html.escape(code)}</pre><a href="{name}.py">Unduh kode</a></details>')
    page = TEMPLATE.replace('__REVIEWS__', ''.join(reviews)).replace('__SOURCES__', ''.join(sources))
    page = page.replace('__DATA__', json.dumps(data).replace('<', '\\u003c'))
    (RESULT_ROOT / 'index.html').write_text(page, encoding='utf-8')
    final = data['rounds']['final']
    baseline = sum(data['baseline'])
    lines = ['PACKING ARENA', '', 'Buka index.html untuk skor dan visualisasi interaktif.', '',
             'HASIL FINAL', f'Baseline best-fit decreasing: {baseline} kardus.']
    for i, s in enumerate(final, 1):
        old = next(x for x in data['rounds']['initial'] if x['name'] == s['name'])
        if s['invalid']:
            lines.append(f"{i}. {s['name'].title()}: {s['invalid']} kasus gagal. Total {sum(r['bins'] for r in s['rows'])} kardus keluaran, skor kardus parsial {s['total_bins']}. Median {s['median_ms']:.3f} ms, maksimum {s['max_ms']:.3f} ms.")
        else:
            lines.append(f"{i}. {s['name'].title()}: {s['total_bins']} kardus, 0 kasus gagal, median {s['median_ms']:.3f} ms, perubahan {s['total_bins']-old['total_bins']:+d} kardus dari ronde awal.")
    lines += ['', 'ULANGI PENGUJIAN', 'Python 3.10 atau lebih baru. Tidak perlu paket tambahan.',
              'Buka terminal dalam folder ini, lalu jalankan:', 'python judge.py --root . --cases cases.json',
              '', 'Perintah tersebut memperbarui results.json. Untuk memperbarui halaman:',
              'python render.py', '', 'Kode awal: round1/. Kode final: scarlet.py, cobalt.py, jade.py.',
              'Kritik silang: review-scarlet.txt, review-cobalt.txt, review-jade.txt.',
              'Optimum hanya terbukti pada kasus yang memiliki nilai optimum di cases.json.',
              'Waktu dapat berubah sesuai beban mesin. Semua angka berasal dari dataset sintetis ini.',
              f"SHA-256 dataset: {data['dataset_sha256']}", f"Seed: {data['seed']}"]
    (RESULT_ROOT / 'README.txt').write_text('\n'.join(lines), encoding='utf-8')
    print('\n'.join(lines[:9]))


if __name__ == '__main__':
    main()
